net.coobird.thumbnailator.filters.ImageFilter magentaFilter = new net.coobird.thumbnailator.filters.ImageFilter() {
    @Override
    public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
        java.awt.image.BufferedImage out = new java.awt.image.BufferedImage(
            img.getWidth(), img.getHeight(), java.awt.image.BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D g = out.createGraphics();
        g.setColor(java.awt.Color.MAGENTA);
        g.fillRect(0, 0, img.getWidth(), img.getHeight());
        g.dispose();
        return out;
    }
};

java.awt.image.BufferedImage result = net.coobird.thumbnailator.Thumbnails.of(sourceImage)
    .size(32, 32)
    .addFilter(magentaFilter)
    .asBufferedImage();

int centerX = result.getWidth() / 2;
int centerY = result.getHeight() / 2;
int centerRgb = result.getRGB(centerX, centerY);
int expectedRgb = java.awt.Color.MAGENTA.getRGB();

assert centerRgb == expectedRgb : "Filter was not applied correctly, expected MAGENTA but got " + Integer.toHexString(centerRgb);
System.out.println("__CHECK__ addFilter " + Integer.toHexString(centerRgb));

